report={'generatedPages':sorted(p.name for p in OUT.glob('*.html')),'vocabularyCount':len(words),'groups':manifest['sources'],'focusCount':len(focus),'storySentences':len(sentences),'modelWordCount':model_count,'meetingMinutes':[{k:m[k] for k in ('n','dur','active')} for m in meetings],'dateStatus':'postponement not approved','originalStoryUnchanged':hashlib.sha256(source.read_bytes()).hexdigest()==manifest['storySha256']}
